    extracted_hostname[hostname_len] = '\0'; // Null-terminate the extracted hostname

    // --- Compare the extracted hostname with the provided domain ---
    size_t extracted_len = strlen(extracted_hostname);
    int is_within_domain = 0;

    if (extracted_len == domain_len) {
        // Exact match (e.g., "example.com" vs "example.com")
        if (strcmp(extracted_hostname, domain) == 0) {
            is_within_domain = 1;
        }
